const GlassCard: React.FC<{
  pillar: any;
  index: number;
  triggerFrame: number;
  accentColor: string;
  textColor: string;
  width: number;
}> = ({ pillar, index, triggerFrame, accentColor, textColor, width }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const localFrame = Math.max(0, frame - triggerFrame);

  const entrance = spring({
    fps,
    frame: localFrame,
    config: { damping: 14, mass: 1.2 },
  });

  const opacity = interpolate(localFrame, [0, 15], [0, 1], {
    extrapolateRight: "clamp",
  });
  const translateY = interpolate(entrance, [0, 1], [100, 0]);
  const scale = interpolate(entrance, [0, 1], [0.95, 1]);

  const renderTitle = () => {
    if (!pillar.highlightWord || !pillar.title.toLowerCase().includes(pillar.highlightWord.toLowerCase())) {
      return pillar.title;
    }
    
    const idx = pillar.title.toLowerCase().indexOf(pillar.highlightWord.toLowerCase());
    if (idx === -1) return pillar.title;

    const before = pillar.title.substring(0, idx);
    const match = pillar.title.substring(idx, idx + pillar.highlightWord.length);
    const after = pillar.title.substring(idx + pillar.highlightWord.length);

    return (
      <>
        {before}
        <span style={{ color: accentColor }}>{match}</span>
        {after}
      </>
    );
  };

  return (
    <div
      style={{
        width: width * 0.88,
        padding: "32px 40px",
        background: "rgba(255, 255, 255, 0.45)",
        backdropFilter: "blur(30px) saturate(160%)",
        WebkitBackdropFilter: "blur(30px) saturate(160%)",
        borderRadius: 30,
        border: "1px solid rgba(255, 255, 255, 0.6)",
        boxShadow: "0 20px 40px rgba(0,0,0,0.06), inset 0 2px 0 rgba(255,255,255,0.7)",
        display: "flex",
        flexDirection: "row",
        alignItems: "center",
        gap: 32,
        opacity,
        transform: `translateY(${translateY}px) scale(${scale})`,
        transition: "none",
        zIndex: 10 - index,
      }}
    >
      <div
        style={{
          width: 90,
          height: 90,
          flexShrink: 0,
          borderRadius: "50%",
          background: `linear-gradient(135deg, ${accentColor}22, ${accentColor}00)`,
          border: `1px solid ${accentColor}44`,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          color: accentColor,
        }}
      >
        <div style={{ width: 44, height: 44 }}>
          {Icons[index % Icons.length]}
        </div>
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
        <div
          style={{
            fontSize: 22,
            color: accentColor,
            fontWeight: 700,
            textTransform: "uppercase",
            letterSpacing: 3,
          }}
        >
          {pillar.label}
        </div>
        <div
          style={{
            fontSize: 48,
            color: textColor,
            fontWeight: 900,
            lineHeight: 1.15,
            letterSpacing: -1.5,
          }}
        >
          {renderTitle()}
        </div>
      </div>
    </div>
  );
};

const Explainer: React.FC<ExplainerProps> = ({
  backgroundColor = "#F9F7F5",
  transparentBackground = false,
  durationInSeconds = 15,
  accentColor = "#F47B5C",
  textColor = "#222222",
  pillars = [
    {
      label: "FACTS",
      title: "Different Facts",
      highlightWord: "Facts",
    },
    {
      label: "RULES",
      title: "Different Rules",
      highlightWord: "Rules",
    },
    {
      label: "DEADLINES",
      title: "Different Deadlines",
      highlightWord: "Deadlines",
    },
  ],
}) => {
  const frame = useCurrentFrame();
  const { width } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Animate the background orbs slightly to showcase the glassmorphism blur effect
  const orb1Y = Math.sin(frame * 0.02) * 150;
  const orb2Y = Math.cos(frame * 0.02) * 150;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        overflow: "hidden",
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
        gap: 32,
      }}
    >
      {/* Background Orbs for Glass Refraction */}
      <div
        style={{
          position: "absolute",
          top: "-10%",
          left: "-10%",
          width: "60%",
          height: "60%",
          background: `radial-gradient(circle, ${accentColor}25 0%, transparent 70%)`,
          filter: "blur(80px)",
          transform: `translateY(${orb1Y}px)`,
          transition: "none",
        }}
      />
      <div
        style={{
          position: "absolute",
          bottom: "-10%",
          right: "-10%",
          width: "70%",
          height: "70%",
          background: `radial-gradient(circle, ${accentColor}15 0%, transparent 70%)`,
          filter: "blur(100px)",
          transform: `translateY(${orb2Y}px)`,
          transition: "none",
        }}
      />
      <div
        style={{
          position: "absolute",
          top: "30%",
          right: "10%",
          width: "40%",
          height: "40%",
          background: `radial-gradient(circle, ${accentColor}20 0%, transparent 70%)`,
          filter: "blur(90px)",
        }}
      />

      {pillars.map((pillar, i) => (
        <GlassCard
          key={`pillar-${i}`}
          pillar={pillar}
          index={i}
          triggerFrame={i * 22 + 10}
          accentColor={accentColor}
          textColor={textColor}
          width={width}
        />
      ))}
    </AbsoluteFill>
  );
};

export default Explainer;